exec('\nfrom __future__ import annotations\nimport time, warnings\nfrom pathlib import Path\nimport numpy as np\nimport pandas as pd\nimport streamlit as st\nimport yfinance as yf\nfrom sklearn.linear_model import Ridge\nfrom sklearn.ensemble import RandomForestRegressor\nfrom sklearn.metrics import mean_squared_error\n\nwarnings.filterwarnings("ignore")\n\nASSETS = ["XME","COPX","PICK","XLB","ITA","XAR","XLI","VIS","PRNT","SPY","DDD","SSYS","MTLS","NNDM"]\nCOMMODITIES = {"Copper":"HG=F","Aluminum":"ALI=F","Oil":"CL=F","Gold":"GC=F","USD":"DX-Y.NYB","VIX":"^VIX"}\nWEIGHTS = {"Copper":0.24,"Aluminum":0.18,"Oil":0.18,"USD":0.16,"VIX":0.16,"Gold":0.08}\nEXPOSURE = {\n"XME":("Mining and metals producers","Direct exposure to metals-cycle, mining margins, commodity demand, and industrial stress."),\n"COPX":("Copper miners","High sensitivity to copper shocks, electrification demand, construction cycle, and industrial demand."),\n"PICK":("Global metals and mining","Diversified mining exposure and broad metals-cycle proxy."),\n"XLB":("US materials sector","Chemicals, materials, industrial input pricing, and macro-cycle sensitivity."),\n"ITA":("Defense and aerospace","Defense/aerospace demand, titanium/aluminum/energy input costs, and geopolitical-risk sensitivity."),\n"XAR":("Aerospace supply chain","Supplier-level aerospace cycle, materials cost pressure, and production-chain stress."),\n"XLI":("Industrials","Industrial-cycle proxy affected by energy, rates, USD, and input-cost stress."),\n"VIS":("Broad industrials","Diversified industrial exposure to macro and manufacturing conditions."),\n"PRNT":("Additive manufacturing ETF","3D printing / advanced manufacturing sentiment and industrial adoption proxy."),\n"DDD":("Additive manufacturing single name","3D printing equity proxy; high idiosyncratic risk."),\n"SSYS":("Additive manufacturing single name","Industrial 3D printing company sensitive to capital spending."),\n"MTLS":("AM software/services","Digital manufacturing and AM services exposure."),\n"NNDM":("Advanced electronics / AM","High-volatility advanced manufacturing proxy."),\n"SPY":("Broad market benchmark","Benchmark to test whether signals are just general market beta.")\n}\nAM_BASKET = ["PRNT","DDD","SSYS","MTLS","NNDM"]\n\ndef safe_period(interval, period):\n    if interval == "1m": return period if period in ["1d","5d"] else "5d"\n    if interval in ["5m","15m","30m","60m"]: return period if period in ["1d","5d","1mo"] else "1mo"\n    return period\n\n@st.cache_data(ttl=60, show_spinner=False)\ndef download_prices(tickers, period, interval):\n    raw = yf.download(tickers, period=period, interval=interval, auto_adjust=True, progress=False, threads=False)\n    if raw.empty: return pd.DataFrame()\n    if isinstance(raw.columns, pd.MultiIndex):\n        prices = raw["Close"].copy()\n    else:\n        prices = raw[["Close"]].copy()\n        if len(tickers) == 1: prices.columns = tickers\n    return prices.dropna(axis=1, how="all").ffill().dropna(how="all")\n\ndef zscore(s, window):\n    return (s - s.rolling(window, min_periods=max(5, window//3)).mean()) / s.rolling(window, min_periods=max(5, window//3)).std()\n\ndef build_features(prices, shock_window):\n    f = pd.DataFrame(index=prices.index)\n    for name, ticker in COMMODITIES.items():\n        if ticker in prices.columns:\n            ret = prices[ticker].pct_change(shock_window)\n            f[f"{name}_shock"] = zscore(ret, max(20, shock_window*4))\n    if f.empty: return f\n    weighted, total = [], 0\n    for name, w in WEIGHTS.items():\n        col = f"{name}_shock"\n        if col in f.columns:\n            weighted.append(f[col]*w); total += w\n    f["CMSI_v2_weighted"] = sum(weighted)/total if weighted and total > 0 else f.mean(axis=1)\n    metal_cols = [c for c in ["Copper_shock","Aluminum_shock","Gold_shock"] if c in f.columns]\n    macro_cols = [c for c in ["USD_shock","VIX_shock","Oil_shock"] if c in f.columns]\n    if metal_cols: f["Metals_Stress"] = f[metal_cols].mean(axis=1)\n    if macro_cols: f["Macro_Risk_Stress"] = f[macro_cols].mean(axis=1)\n    return f.replace([np.inf,-np.inf], np.nan).dropna()\n\ndef stress_label(x):\n    if x >= 2: return "Extreme stress", "Supply-chain / macro stress is unusually high."\n    if x >= 1: return "Elevated stress", "Stress is above normal; watch industrial drawdown risk."\n    if x <= -1: return "Relief / easing", "Stress indicators are below normal."\n    return "Normal", "No major critical-materials stress signal."\n\ndef corr_table(features, y):\n    rows = []\n    for col in features.columns:\n        a = pd.concat([features[col], y], axis=1, join="inner").dropna()\n        if len(a) > 20:\n            rows.append({"feature":col,"spearman_ic":a.iloc[:,0].corr(a.iloc[:,1], method="spearman"),"pearson_corr":a.iloc[:,0].corr(a.iloc[:,1]),"rows":len(a)})\n    return pd.DataFrame(rows).sort_values("spearman_ic", ascending=False) if rows else pd.DataFrame()\n\ndef train(df, cols, model_name):\n    if len(df) < 80: return None, None, None, "Not enough rows. Use longer period or daily interval."\n    split = int(len(df)*0.75)\n    train, test = df.iloc[:split], df.iloc[split:]\n    Xtr, ytr = train[cols].fillna(0), train["future_return"].astype(float)\n    Xte, yte = test[cols].fillna(0), test["future_return"].astype(float)\n    model = RandomForestRegressor(n_estimators=200, max_depth=4, random_state=42) if model_name=="RandomForest" else Ridge(alpha=10.0)\n    model.fit(Xtr, ytr)\n    pred = model.predict(Xte)\n    res = test.copy(); res["prediction"] = pred\n    corr = pd.Series(pred).corr(pd.Series(yte.values)); corr = 0.0 if pd.isna(corr) else float(corr)\n    return model, res, {"rmse":float(mean_squared_error(yte, pred)**0.5),"prediction_corr":corr,"test_rows":len(test)}, None\n\ndef importance(model, cols):\n    if model is None: return pd.Series(dtype=float)\n    vals = model.feature_importances_ if hasattr(model, "feature_importances_") else np.abs(getattr(model, "coef_", np.zeros(len(cols))))\n    return pd.Series(vals, index=cols).sort_values(ascending=False)\n\ndef warnings_for(asset, features, cdf):\n    latest = features.iloc[-1]\n    cmsi = latest.get("CMSI_v2_weighted", np.nan); metals = latest.get("Metals_Stress", np.nan); macro = latest.get("Macro_Risk_Stress", np.nan)\n    out = []\n    if pd.notna(cmsi) and cmsi > 1: out.append("CMSI is elevated: industrial and materials-linked drawdown risk may be higher.")\n    if pd.notna(cmsi) and cmsi < -1: out.append("CMSI is easing: critical-materials stress is below normal.")\n    if asset in ["ITA","XAR"] and pd.notna(macro) and macro > 1: out.append("Aerospace/defense watch: macro/energy stress is elevated.")\n    if asset in ["XME","COPX","PICK"] and pd.notna(metals) and abs(metals) > 1: out.append("Mining/metals watch: metals stress deserves lead-lag testing.")\n    if asset in AM_BASKET and pd.notna(cmsi) and abs(cmsi) > 1: out.append("AM watch: AM-linked equities may be sensitive to industrial risk appetite and input-cost stress.")\n    if not cdf.empty:\n        top = cdf.iloc[0]; out.append(f"Top lead-lag candidate: {top[\'feature\']} with Spearman IC {top[\'spearman_ic\']:.3f}.")\n    return out or ["No strong stress warning. Neutral research state."]\n\ndef backtest(res):\n    bt = res[["prediction","future_return"]].dropna().copy()\n    if bt.empty: return bt\n    bt["position"] = np.where(bt["prediction"] > 0, 1.0, -1.0)\n    bt["strategy_return"] = bt["position"] * bt["future_return"]\n    bt["equity"] = (1 + bt["strategy_return"].fillna(0)).cumprod()\n    return bt\n\nst.set_page_config(page_title="MatQuantLab V3", layout="wide")\nst.title("MatQuantLab V3 — Critical Materials Intelligence Layer")\nst.caption("Materials-informed ML dashboard for cross-asset stress, lead-lag signals, industrial risk, and additive manufacturing watchlists. Research only, not investment advice.")\n\nwith st.sidebar:\n    st.header("Experiment Controls")\n    asset = st.selectbox("Target asset", ASSETS, index=ASSETS.index("XME"))\n    interval = st.selectbox("Interval", ["1m","5m","15m","30m","60m","1d"], index=1)\n    period = st.selectbox("Period", ["1d","5d","1mo","3mo","6mo","1y"], index=1)\n    model_name = st.selectbox("Model", ["Ridge","RandomForest"])\n    horizon = st.slider("Prediction horizon in bars", 1, 120, 12)\n    shock_window = st.slider("Shock window in bars", 3, 80, 20)\n    auto = st.toggle("Auto-refresh every 60 seconds", value=False)\n    if st.button("Refresh latest data"):\n        st.cache_data.clear(); st.rerun()\nif auto:\n    time.sleep(60); st.cache_data.clear(); st.rerun()\n\ntickers = sorted(set([asset] + list(COMMODITIES.values()) + AM_BASKET))\nprices = download_prices(tickers, safe_period(interval, period), interval)\nif prices.empty or asset not in prices.columns:\n    st.error("Could not download data. Try another period, interval, or asset."); st.stop()\n\nfeatures = build_features(prices, shock_window)\nif features.empty:\n    st.error("Could not build features. Try longer period or bigger interval."); st.stop()\n\ny = prices[asset].pct_change(horizon).shift(-horizon).rename("future_return")\ndf = pd.concat([features, y], axis=1, join="inner").dropna()\ncdf = corr_table(features, y)\ncmsi = float(features["CMSI_v2_weighted"].iloc[-1])\nlabel, desc = stress_label(cmsi)\ntheme, logic = EXPOSURE.get(asset, ("Custom asset","No exposure logic configured."))\n\na,b,c,d = st.columns(4)\na.metric("Target asset", asset)\nb.metric("Latest price", f"{prices[asset].dropna().iloc[-1]:.2f}")\nc.metric("CMSI v2", f"{cmsi:.2f}")\nd.metric("Stress regime", label)\nst.info(desc)\nst.markdown(f"**Exposure logic — {theme}:** {logic}")\n\ntabs = st.tabs(["Industrial Stress Radar","Lead-Lag Lab","ML Explainability","AM Watchlist","Backtest","Raw Data"])\n\nwith tabs[0]:\n    st.subheader("Industrial Stress Radar")\n    cols = [x for x in ["CMSI_v2_weighted","Metals_Stress","Macro_Risk_Stress"] if x in features.columns]\n    st.line_chart(features[cols])\n    st.markdown("### Early-warning notes")\n    for w in warnings_for(asset, features, cdf): st.write("• " + w)\n    drivers = features.iloc[-1][[x for x in features.columns if x.endswith("_shock")]].sort_values(key=lambda s: s.abs(), ascending=False)\n    st.markdown("### Current strongest stress drivers")\n    st.dataframe(drivers.rename("latest_z_score").to_frame(), use_container_width=True)\n\nwith tabs[1]:\n    st.subheader("Lead-Lag Signal Lab")\n    st.write("Tests relationship between each stress feature and future return at selected horizon.")\n    st.dataframe(cdf, use_container_width=True)\n    if not cdf.empty: st.bar_chart(cdf.set_index("feature")["spearman_ic"])\n\nwith tabs[2]:\n    st.subheader("ML Explainability")\n    cols = list(features.columns)\n    model, res, metrics, err = train(df, cols, model_name)\n    if err:\n        st.warning(err)\n    else:\n        m1,m2,m3 = st.columns(3)\n        m1.metric("RMSE", f"{metrics[\'rmse\']:.5f}")\n        m2.metric("Prediction corr", f"{metrics[\'prediction_corr\']:.3f}")\n        m3.metric("Test rows", metrics["test_rows"])\n        st.line_chart(res[["prediction","future_return"]])\n        imp = importance(model, cols)\n        st.bar_chart(imp)\n        latest_pred = float(model.predict(features.iloc[[-1]][cols].fillna(0))[0])\n        st.write(f"Latest model-implied {horizon}-bar pressure for **{asset}**: **{\'positive\' if latest_pred > 0 else \'negative\'}** ({latest_pred:.4f}).")\n\nwith tabs[3]:\n    st.subheader("Additive Manufacturing Watchlist")\n    available = [x for x in AM_BASKET if x in prices.columns]\n    if available:\n        am_prices = prices[available].dropna(how="all")\n        st.line_chart(am_prices / am_prices.iloc[0])\n        rows = []\n        for t in available:\n            yy = prices[t].pct_change(horizon).shift(-horizon).rename("future_return")\n            aligned = pd.concat([features["CMSI_v2_weighted"], yy], axis=1, join="inner").dropna()\n            if len(aligned) > 20: rows.append({"asset":t,"CMSI_spearman_ic":aligned.iloc[:,0].corr(aligned.iloc[:,1], method="spearman")})\n        st.dataframe(pd.DataFrame(rows), use_container_width=True)\n    else:\n        st.warning("No AM basket tickers available.")\n\nwith tabs[4]:\n    st.subheader("Toy Research Backtest")\n    if "res" in locals() and res is not None:\n        bt = backtest(res)\n        if not bt.empty:\n            st.line_chart(bt["equity"])\n            st.dataframe(bt.tail(30), use_container_width=True)\n        else: st.warning("Backtest empty.")\n    else: st.warning("Run ML tab first.")\n\nwith tabs[5]:\n    st.subheader("Prices")\n    st.dataframe(prices.tail(50), use_container_width=True)\n    st.subheader("Features")\n    st.dataframe(features.tail(50), use_container_width=True)\n\nst.caption("Data source: Yahoo Finance via yfinance. Research demonstration only; not financial advice.")\n')
